       System.Collections.Generic.List<object[]> trupi = new System.Collections.Generic.List<object[]>();
        private double totalVleftaMeTVSH = 0;

private void Rap_Format_Printimi_Model12_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox2.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

 string magdest = "";
            string mag = "";
            this.Detail.Controls.Add(CreateXRTable());
            System.Data.DataTable dt = ((System.Data.DataSet)(this.DataSource)).Tables[0];
  trupi.Clear();
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                //object NR = dt.Rows[i]["calculatedField1"];
                object KODI = dt.Rows[i]["KODARTIKULLI"];
                object kodbari = dt.Rows[i]["KODBARI"];
                object PERSHKRIMI = dt.Rows[i]["PERSHKRIMARTIKULLI"];
                object NJESI = dt.Rows[i]["KODNJESIA"];
                object SASIA =  dt.Rows[i]["SASIA"];
                object CMIMI = (dt.Rows[i]["CMIMIMETVSH"]) == DBNull.Value ? 0.00 : dt.Rows[i]["CMIMIMETVSH"];
                double vleftametvsh1;
                if (dt.Rows[i]["SASIA"] != DBNull.Value && dt.Rows[i]["CMIMIMETVSH"] != DBNull.Value
                    && dt.Rows[i]["SASIA"] != "" && dt.Rows[i]["CMIMIMETVSH"] != "")
                {
                    vleftametvsh1 = Convert.ToDouble(dt.Rows[i]["SASIA"]) * Convert.ToDouble(dt.Rows[i]["CMIMIMETVSH"]);
                    // object VLEFTAMETVSH = Convert.ToInt32(dt.Rows[i]["SASIA"]) * Convert.ToDouble(dt.Rows[i]["CMIMBAZE"]); //[SASIA] *ToDouble([CMIMBAZE])
                }
                else vleftametvsh1=0.00;
                object VLEFTAMETVSH = Math.Round(vleftametvsh1, 2);
                totalVleftaMeTVSH += vleftametvsh1;

                if (i == 0 && (dt.Rows[i]["PERSHKRIMKODMAG"].ToString() != "" || dt.Rows[i]["PERSHKRIMKODMAG"].ToString() != null))
                { mag = dt.Rows[i]["PERSHKRIMKODMAG"].ToString(); }
                else if (i != 0 && (dt.Rows[i]["PERSHKRIMKODMAG"].ToString() != "" || dt.Rows[i]["PERSHKRIMKODMAG"].ToString() != null))
                {
                    if (mag != dt.Rows[i]["PERSHKRIMKODMAG"].ToString())
                    {
                        xrLabel18.Visible = false;
                        xrLabel46.Visible = false;

                    }

                }

                if (i== 0 && (dt.Rows[i]["PERSHKRIMKODMAGDEST"].ToString() != "" || dt.Rows[i]["PERSHKRIMKODMAGDEST"].ToString() != null))
                { magdest = dt.Rows[i]["PERSHKRIMKODMAGDEST"].ToString(); }
                else    if (i!= 0 && (dt.Rows[i]["PERSHKRIMKODMAGDEST"].ToString() != "" || dt.Rows[i]["PERSHKRIMKODMAGDEST"].ToString() != null))
                {
                    if (magdest != dt.Rows[i]["PERSHKRIMKODMAGDEST"].ToString())
                    {
                        xrLabel19.Visible  = false;
                        xrLabel48.Visible = false;

                    }

                }
                object HYRJEMAG = dt.Rows[i]["PERSHKRIMKODMAG"];
                object DALJEMAG = dt.Rows[i]["PERSHKRIMKODMAGDEST"];

                object[] obj = new object[10];
                obj[0] = (i + 1).ToString();
                obj[1] = kodbari;
                obj[2] = PERSHKRIMI;
                obj[3] = NJESI;
                obj[4] = SASIA;
                obj[5] = CMIMI;
                obj[6] = VLEFTAMETVSH;
                obj[7] = HYRJEMAG;
                obj[8] = DALJEMAG;
                obj[9] = KODI;
                trupi.Add(obj);
            }
}
     private XRTable CreateXRTable()
        {
            int i = 0;
            XRTable table = new XRTable();
            table.Size = new Size(650, 25);//.HeightF = 25f;
            table.BeginInit();
            //table.WidthF = 650f;
            table.LocationF = new DevExpress.Utils.PointFloat(0F, 0F);
            if (trupi.Count > 0)
            {
                for (int j = table.Rows.Count - 1; j >= 1; j--)
                {
                    table.Rows.RemoveAt(j);
                }
                foreach (object[] obj in trupi)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 25f;

                    XRTableCell nr = new XRTableCell();
                    nr.WidthF = 35.54f;
                   nr.Name = "nr" ;//+ i.ToString();
                    nr.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    nr.Text = obj[0].ToString();
                    nr.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleCenter;
                    nr.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    nr.BorderColor = System.Drawing.Color.Silver;
                    nr.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(nr);

                    XRTableCell KODI = new XRTableCell();
                    KODI.WidthF = 55f;
                 KODI.Name = "KODARTIKULLI";
                    KODI.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    KODI.Text = obj[9].ToString();
                    KODI.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleCenter;
                    KODI.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    KODI.BorderColor = System.Drawing.Color.Silver;
                    KODI.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(KODI);

                    XRTableCell nrArt = new XRTableCell();
                    nrArt.WidthF = 100.49f;
                    nrArt.Name = "nrArt" ;//+ i.ToString();
                    nrArt.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    nrArt.Text = obj[1].ToString();
                    nrArt.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleCenter;
                    nrArt.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    nrArt.BorderColor = System.Drawing.Color.Silver;
                    nrArt.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(nrArt);

                    XRTableCell PERSHKRIMI = new XRTableCell();
                    PERSHKRIMI.WidthF = 201.72f;
                    PERSHKRIMI.Name = "PERSHKRIMI" ;//+ i.ToString();
                    PERSHKRIMI.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    PERSHKRIMI.Text = obj[2].ToString();
                    PERSHKRIMI.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleCenter;
                    PERSHKRIMI.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    PERSHKRIMI.BorderColor = System.Drawing.Color.Silver;
                    PERSHKRIMI.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(PERSHKRIMI);

                    XRTableCell NJESI = new XRTableCell();
                    NJESI.WidthF = 74.4f;
                    NJESI.Name = "NJESI" ;//+ i.ToString();
                    NJESI.Text = obj[3].ToString();
                    NJESI.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleCenter;
                    NJESI.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    NJESI.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    NJESI.BorderColor = System.Drawing.Color.Silver;
                    NJESI.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(NJESI);

                    XRTableCell SASIA = new XRTableCell();
                    SASIA.WidthF = 71.37f;
               SASIA.Name = "SASIA";// + i.ToString();
                    SASIA.Text = Convert.ToString(obj[4]);
                    SASIA.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    SASIA.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    SASIA.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    SASIA.BorderColor = System.Drawing.Color.Silver;
                    SASIA.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(SASIA);

                    XRTableCell CMIMI = new XRTableCell();
                    CMIMI.WidthF = 89.26f;
                    CMIMI.Name = "CMIMIMETVSH";// + i.ToString();
                    CMIMI.Text = String.Format("{0:N2}", obj[5]);
                    CMIMI.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    CMIMI.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    CMIMI.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    CMIMI.BorderColor = System.Drawing.Color.Silver;
                    CMIMI.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(CMIMI);

                    XRTableCell VLEFTAMETVSH = new XRTableCell();
                    VLEFTAMETVSH.WidthF = 122.22f;
                  VLEFTAMETVSH.Name = "VLEFTAMETVSH" ;//+ i.ToString();
                    VLEFTAMETVSH.Text = String.Format("{0:N2}", obj[6]);
                    VLEFTAMETVSH.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    VLEFTAMETVSH.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    VLEFTAMETVSH.Borders = DevExpress.XtraPrinting.BorderSide.All;
                    VLEFTAMETVSH.BorderColor = System.Drawing.Color.Silver;
                    VLEFTAMETVSH.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(VLEFTAMETVSH);

                    table.Rows.Add(rr);
                    i++;
                }
                table.EndInit();
            }
            return table;
        }

